"""Tests for the executive scorecard (gen.py / rag.py / render.py)."""
import json
import re
from datetime import datetime
from html.parser import HTMLParser

import gen
import rag
import render


# ---------- tiny stdlib HTML parsing helpers ----------

class ScorecardParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []          # list of (kpi, status) for table rows
        self.time_attrs = None  # attrs of <time>
        self.summary_text = None
        self._in_summary = False
        self._in_td = False
        self._cells = []
        self._current_cells = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "tr" and "data-status" in a:
            self._current_cells = {"kpi": a.get("data-kpi"), "status": a["data-status"]}
        elif tag == "td":
            self._in_td = True
        elif tag == "time":
            self.time_attrs = a
        elif tag == "p" and a.get("id") == "summary":
            self._in_summary = True

    def handle_endtag(self, tag):
        if tag == "tr" and self._current_cells is not None:
            self.rows.append((self._current_cells["kpi"], self._current_cells["status"]))
            self._current_cells = None
        elif tag == "td":
            self._in_td = False
        elif tag == "p" and self._in_summary:
            self._in_summary = False

    def handle_data(self, data):
        if self._current_cells is not None:
            self._current_cells.setdefault("texts", []).append(data.strip())
        if self._in_summary:
            self.summary_text = (self.summary_text or "") + data.strip()


def parse_html(html: str) -> ScorecardParser:
    p = ScorecardParser()
    p.feed(html)
    return p


def load_data():
    with open("data.json") as f:
        return json.load(f)


def load_rendered():
    with open("scorecard.html") as f:
        return f.read()


# ---------- pipeline fixtures ----------

def test_generated_data_shape():
    kpis = {k["name"]: k for k in gen.generate()}
    assert set(kpis) == {"revenue", "gross_margin_pct", "nps", "churn_pct", "cac", "uptime_pct"}
    up = kpis["uptime_pct"]
    assert up["target"] == 99.9 and 99.0 <= up["actual"] <= 100.0
    for name, k in kpis.items():
        if name != "uptime_pct":
            assert k["target"] * 0.85 <= k["actual"] <= k["target"] * 1.15


# ---------- core RAG logic ----------

def test_lower_is_better_beating_target_by_20pct_is_green_not_red():
    # churn actual 20% BELOW target -> beating target -> must be GREEN
    assert rag.status("lower_is_better", 4.0, 4.0 * 0.80) == "GREEN"
    assert rag.status("lower_is_better", 4.0, 4.0 * 0.80) != "RED"
    # same for cac
    assert rag.status("lower_is_better", 320.0, 320.0 * 0.80) == "GREEN"


def test_higher_is_better_beating_target_is_green():
    assert rag.status("higher_is_better", 100.0, 120.0) == "GREEN"


def test_forced_boundary_fixtures_both_directions():
    t = 100.0
    # Exactly on the 3 percent boundary (ratio == 0.97): GREEN per documented rule
    assert rag.status("higher_is_better", t, 97.0) == "GREEN"
    assert rag.status("lower_is_better", t, t / 0.97) == "GREEN"
    # Just inside 3 percent: GREEN
    assert rag.status("higher_is_better", t, 97.1) == "GREEN"
    assert rag.status("lower_is_better", t, t / 0.971) == "GREEN"

    # Exactly on the 10 percent boundary (ratio == 0.90): AMBER per documented rule
    assert rag.status("higher_is_better", t, 90.0) == "AMBER"
    assert rag.status("lower_is_better", t, t / 0.90) == "AMBER"

    # Beyond 10 percent: RED in both directions
    assert rag.status("higher_is_better", t, 89.9) == "RED"
    assert rag.status("lower_is_better", t, t / 0.899) == "RED"


# ---------- rendered scorecard ----------

def test_every_status_recomputed_honoring_direction():
    data = load_data()
    parser = parse_html(load_rendered())
    rows = dict(parser.rows)

    for k in data["kpis"]:
        expected = rag.status(k["direction"], k["target"], k["actual"])
        assert k["name"] in rows, f"missing row for {k['name']}"
        assert rows[k["name"]] == expected, (
            f"{k['name']}: rendered {rows[k['name']]}, recomputed {expected}"
        )
        # direction map agrees with the data
        assert rag.DIRECTIONS[k["name"]] == k["direction"]
    assert set(rows) == {k["name"] for k in data["kpis"]}


def test_summary_counts_match_table_statuses():
    parser = parse_html(load_rendered())
    from collections import Counter
    counts = Counter(s for _, s in parser.rows)

    m = re.fullmatch(
        r"(\d+) green / (\d+) amber / (\d+) red", parser.summary_text
    )
    assert m, f"summary line has unexpected format: {parser.summary_text!r}"
    assert int(m.group(1)) == counts["GREEN"]
    assert int(m.group(2)) == counts["AMBER"]
    assert int(m.group(3)) == counts["RED"]


def test_time_tag_parses_as_iso_8601():
    parser = parse_html(load_rendered())
    dt_attr = parser.time_attrs["datetime"]
    parsed = datetime.fromisoformat(dt_attr.replace("Z", "+00:00"))
    assert parsed.tzinfo is not None

